import styled from '@emotion/styled';
import { Divider, Heading } from 'components/UI';
import { theme } from 'theme';

export const StyledHeaderContainerRoot = styled.div({
  display: 'flex',
  flexDirection: 'column',
});

export const StyledHeaderContentTitleContainer = styled.div({
  display: 'flex',
  gap: '8px',
  alignItems: 'baseline',
  marginBottom: '12px',
});

interface StyledHeaderContentBodyContainerProps {
  $noPadding?: boolean;
}

export const StyledHeaderContentBodyContainer =
  styled.div<StyledHeaderContentBodyContainerProps>(({ $noPadding }) => ({
    display: 'flex',
    flexDirection: 'column',
    gap: '8px',
    paddingLeft: '20px',
    fontFamily: theme.fonts.paragraph,

    p: {
      margin: 0,
    },

    ...($noPadding && { paddingLeft: 0 }),
  }));

type HeaderContentIconType = 'circle' | 'block' | 'none';

interface StyledHeaderContentIconProps {
  $type?: HeaderContentIconType;
}

export const StyledHeaderContentIcon = styled.div<StyledHeaderContentIconProps>(
  ({ $type = 'circle' }) => ({
    width: '12px',
    height: '12px',
    background: '#E5B33A',
    borderRadius: '50%',
    marginBottom: 'auto',
    marginTop: '12px',
    ...($type === 'block' && {
      width: '20px',
      height: '20px',
      borderRadius: '4px',
    }),
    ...($type === 'none' && { display: 'none' }),
  }),
);

export const StyledHeaderContentTitle = styled(Heading)({
  fontSize: '24px',
  fontFamily: theme.fonts.heading,
  fontWeight: 'bold',
});

type HeaderContentSubtitleColor = 'black' | 'grey';

interface StyledHeaderContentSubTitleProps {
  $color?: HeaderContentSubtitleColor;
}

export const StyledHeaderContentSubTitle = styled(Heading, {
  shouldForwardProp: (prop) => prop !== '$color',
})<StyledHeaderContentSubTitleProps>(({ $color }) => ({
  fontWeight: 'regular',
  margin: '0',
  ...($color === 'black' && { color: theme.colors.neutral100 }),
  ...($color === 'grey' && { color: theme.colors.txt.secondary }),
}));

export const StyledHeaderContentDivider = styled(Divider)({ margin: '1rem 0' });
